/* Spot-check the generated HD44780 ROM A00 font tables against the
 * datasheet's well-known glyphs ('0', 'A', the all-pixels-on 0xFF
 * 5x10 block). The full table has 256 5x8 entries + 32 5x10 entries;
 * if the extraction script drifts (wrong row pitch, off-by-one column,
 * wrong bit ordering), one of these asserts trips.
 *
 * The font header is autogenerated from the datasheet PNG by
 *   tools/extract_hd44780_font.py
 * and committed into the chips/ dir as hd44780_a00_font.h. */

#include <stdint.h>
#include <string.h>

#include "greatest.h"
#include "../chips/hd44780_a00_font.h"

TEST glyph_0_matches_datasheet(void) {
    /* HD44780 '0' (5x8): canonical pattern, row 7 = cursor row = 0. */
    static const uint8_t expected[8] = {
        0x0E, /* .###.  bit 4 = leftmost */
        0x11, /* #...#  */
        0x13, /* #..##  */
        0x15, /* #.#.#  */
        0x19, /* ##..#  */
        0x11, /* #...#  */
        0x0E, /* .###.  */
        0x00,
    };
    for (int i = 0; i < 8; i++) {
        ASSERT_EQ_FMT(expected[i], hd44780_a00_font_5x8['0'][i], "%02x");
    }
    PASS();
}

TEST glyph_A_matches_datasheet(void) {
    static const uint8_t expected[8] = {
        0x0E, /* .###. */
        0x11, /* #...# */
        0x11, /* #...# */
        0x11, /* #...# */
        0x1F, /* ##### */
        0x11, /* #...# */
        0x11, /* #...# */
        0x00,
    };
    for (int i = 0; i < 8; i++) {
        ASSERT_EQ_FMT(expected[i], hd44780_a00_font_5x8['A'][i], "%02x");
    }
    PASS();
}

TEST glyph_space_is_blank(void) {
    for (int i = 0; i < 8; i++) {
        ASSERT_EQ_FMT(0x00, hd44780_a00_font_5x8[' '][i], "%02x");
    }
    PASS();
}

TEST glyph_FF_is_solid_5x10_block(void) {
    /* 0xFF in ROM A00 is the all-dots-on block. In 5x10 form that's
     * 10 rows of 0x1F (all 5 columns lit). */
    for (int i = 0; i < 10; i++) {
        ASSERT_EQ_FMT(0x1F, hd44780_a00_font_5x10[0xFF - 0xE0][i], "%02x");
    }
    PASS();
}

TEST glyph_F0_has_descender(void) {
    /* The 5x10 glyph at 0xF0 has its baseline above the descender
     * region: rows 7..9 are non-empty (descender), which can't happen
     * for a 5x8 char. This confirms we sampled rows 8 and 9, not just
     * 0..7. */
    int descender_bits = 0;
    for (int i = 7; i < 10; i++) {
        descender_bits |= hd44780_a00_font_5x10[0xF0 - 0xE0][i];
    }
    ASSERT(descender_bits != 0);
    PASS();
}

TEST cgram_placeholder_cells_are_blank(void) {
    /* Codes 0x00..0x0F occupy column 0000 of the datasheet table where
     * the cells hold the labels "CG RAM (1)" etc., not actual glyph
     * data. The extraction explicitly zeros these so the runtime can
     * use them for CGRAM patterns. */
    for (int code = 0x00; code <= 0x0F; code++) {
        for (int i = 0; i < 8; i++) {
            ASSERT_EQ_FMT(0x00, hd44780_a00_font_5x8[code][i], "%02x");
        }
    }
    PASS();
}

SUITE(hd44780_font_suite) {
    RUN_TEST(glyph_0_matches_datasheet);
    RUN_TEST(glyph_A_matches_datasheet);
    RUN_TEST(glyph_space_is_blank);
    RUN_TEST(glyph_FF_is_solid_5x10_block);
    RUN_TEST(glyph_F0_has_descender);
    RUN_TEST(cgram_placeholder_cells_are_blank);
}

GREATEST_MAIN_DEFS();
int main(int argc, char **argv) {
    GREATEST_MAIN_BEGIN();
    RUN_SUITE(hd44780_font_suite);
    GREATEST_MAIN_END();
}
